// The resolved locations (offsets from the module base; 0 = not found), resolved once.
inline const uintptr_t* Resolved(HMODULE engine, size_t* found = nullptr) {
    static uintptr_t got[kSiteCount];
    static size_t n = sites::ResolveAll(engine, kSites, kSiteCount, got);
    if (found) *found = n;
    return got;
}

